        // nearest=min / farthest=max for DISTANCE metrics, with score in metric units.
        void NearestFarthestDistance()
        {
            //  r0=(0,0) r1=(3,4) r2=(1,1); q=(0,0).
            var A = new floatMxN(3, 2, Allocator.Temp);
            A[0, 0] = (float)0; A[0, 1] = (float)0;
            A[1, 0] = (float)3; A[1, 1] = (float)4;
            A[2, 0] = (float)1; A[2, 1] = (float)1;
            var q = new floatN(2, Allocator.Temp);
            q[0] = (float)0; q[1] = (float)0;

            // SqEuclidean: distances 0, 25, 2. nearest=r0 (score 0), farthest=r1 (score 25).
            Query.nearestRow(in A, in q, Metric.SqEuclidean, out int ni, out float ns);
            AssertEqI(ni, 0); AssertClose(ns, (float)0, fEps());

            Query.farthestRow(in A, in q, Metric.SqEuclidean, out int fi, out float fs);
            AssertEqI(fi, 1); AssertClose(fs, (float)25, fEps());   // squared units, not sqrt

            // Euclidean score is in euclidean units: farthest = 5.
            Query.farthestRow(in A, in q, Metric.Euclidean, out int fi2, out float fs2);
            AssertEqI(fi2, 1); AssertClose(fs2, (float)5, sqrtEps());
        }

        // The KEY direction flip: similarity metrics (Cosine/Dot) -> nearest = MAX, farthest = MIN.
        void NearestFarthestSimilarity()
        {
            //  r0=(1,0) r1=(10,0) r2=(-5,0); q=(1,0).
            //  Dot: 1, 10, -5  -> nearest(max)=r1, farthest(min)=r2.
            var A = new floatMxN(3, 2, Allocator.Temp);
            A[0, 0] = (float)1;    A[0, 1] = (float)0;
            A[1, 0] = (float)10;   A[1, 1] = (float)0;
            A[2, 0] = (float)(-5); A[2, 1] = (float)0;
            var q = new floatN(2, Allocator.Temp);
            q[0] = (float)1; q[1] = (float)0;

            Query.nearestRow(in A, in q, Metric.Dot, out int ni, out float ns);
            AssertEqI(ni, 1); AssertClose(ns, (float)10, fEps());

            Query.farthestRow(in A, in q, Metric.Dot, out int fi, out float fs);
            AssertEqI(fi, 2); AssertClose(fs, (float)(-5), fEps());

            // Cosine: r0 & r1 are parallel to q (cos=1), r2 anti-parallel (cos=-1).
            // nearest = max cosine -> first of the two cos=1 rows (r0); farthest = r2.
            Query.nearestRow(in A, in q, Metric.Cosine, out int cni, out float cns);
            AssertEqI(cni, 0); AssertClose(cns, (float)1, sqrtEps());

            Query.farthestRow(in A, in q, Metric.Cosine, out int cfi, out float cfs);
            AssertEqI(cfi, 2); AssertClose(cfs, (float)(-1), sqrtEps());

            // Column twins: nearestColumn/farthestColumn with a similarity metric.
            // Columns of A as vectors of length 3: c0=(1,10,-5), c1=(0,0,0). q3=(1,0,0).
            var q3 = new floatN(3, Allocator.Temp);
            q3[0] = (float)1; q3[1] = (float)0; q3[2] = (float)0;
            // Dot: c0·q3 = 1 ; c1·q3 = 0 -> nearest(max)=c0, farthest(min)=c1.
            Query.nearestColumn(in A, in q3, Metric.Dot, out int cni2, out float cns2);
            AssertEqI(cni2, 0); AssertClose(cns2, (float)1, fEps());
            Query.farthestColumn(in A, in q3, Metric.Dot, out int cfi2, out float cfs2);
            AssertEqI(cfi2, 1); AssertClose(cfs2, (float)0, fEps());
        }

        // kNearestRows vs brute-force reference, sorted best-first, ties deterministic.
        void KNearestBruteForce()
        {
            int M = 6, N = 3;
            var A = GenerateOP.floatRandomMat(M, N, -3f, 3f, 424242, allocator: Allocator.Temp);
            var q = new floatN(N, Allocator.Temp);
            q[0] = (float)0.5; q[1] = (float)(-1); q[2] = (float)2;

            int k = 3;
            var idx = new Indices(k, Allocator.Temp);
            var scores = new floatN(k, Allocator.Temp);

            // --- distance metric (SqEuclidean) ---
            int cnt = Query.kNearestRows(in A, in q, k, Metric.SqEuclidean, ref idx, ref scores);
            AssertEqI(cnt, k);

            // Brute-force all scores then verify: returned set is the k smallest, sorted ascending.
            var all = new floatN(M, Allocator.Temp);
            Query.distancesToRow(in A, in q, Metric.SqEuclidean, ref all);
            // sorted ascending => scores[0] <= scores[1] <= scores[2]
            for (int i = 0; i + 1 < cnt; i++)
                AssertTrue(scores[i] <= scores[i + 1] + sqrtEps());
            // each returned score equals the metric of its returned index
            for (int i = 0; i < cnt; i++)
                AssertClose(scores[i], all[idx[i]], sqrtEps());
            // the k-th best returned score is <= every non-selected row's score
            float kth = scores[cnt - 1];
            for (int r = 0; r < M; r++)
            {
                bool selected = false;
                for (int i = 0; i < cnt; i++) if (idx[i] == r) selected = true;
                if (!selected) AssertTrue(all[r] >= kth - sqrtEps());
            }

            // --- similarity metric (Dot): best-first = DESCENDING ---
            var idx2 = new Indices(k, Allocator.Temp);
            var scores2 = new floatN(k, Allocator.Temp);
            int cnt2 = Query.kNearestRows(in A, in q, k, Metric.Dot, ref idx2, ref scores2);
            AssertEqI(cnt2, k);
            var allDot = new floatN(M, Allocator.Temp);
            Query.distancesToRow(in A, in q, Metric.Dot, ref allDot);
            for (int i = 0; i + 1 < cnt2; i++)
                AssertTrue(scores2[i] >= scores2[i + 1] - sqrtEps());
            for (int i = 0; i < cnt2; i++)
                AssertClose(scores2[i], allDot[idx2[i]], sqrtEps());
            float kthDot = scores2[cnt2 - 1];
            for (int r = 0; r < M; r++)
            {
                bool selected = false;
                for (int i = 0; i < cnt2; i++) if (idx2[i] == r) selected = true;
                if (!selected) AssertTrue(allDot[r] <= kthDot + sqrtEps());
            }
        }

        // k > M_Rows clamps to count; k=0 returns 0; ties handled deterministically.
        void KNearestClampAndZero()
        {
            int M = 3, N = 2;
            var A = new floatMxN(M, N, Allocator.Temp);
            // all rows identical distance from q -> a full tie; clamp must still return M and
            // produce a valid permutation of {0,1,2} (deterministic insertion order = ascending).
            A[0, 0] = (float)1; A[0, 1] = (float)0;
            A[1, 0] = (float)0; A[1, 1] = (float)1;
            A[2, 0] = (float)(-1); A[2, 1] = (float)0;
            var q = new floatN(N, Allocator.Temp);
            q[0] = (float)0; q[1] = (float)0;   // every row at SqEuclidean distance 1.

            // k = 10 > M -> clamp to 3.
            int k = 10;
            var idx = new Indices(k, Allocator.Temp);
            var scores = new floatN(k, Allocator.Temp);
            int cnt = Query.kNearestRows(in A, in q, k, Metric.SqEuclidean, ref idx, ref scores);
            AssertEqI(cnt, 3);
            // all returned scores == 1
            for (int i = 0; i < cnt; i++) AssertClose(scores[i], (float)1, fEps());
            // indices form a permutation of {0,1,2}; on a pure tie insertion keeps first-seen order.
            AssertEqI(idx[0], 0); AssertEqI(idx[1], 1); AssertEqI(idx[2], 2);

            // k = 0 -> returns 0, writes nothing.
            int z = Query.kNearestRows(in A, in q, 0, Metric.SqEuclidean, ref idx, ref scores);
            AssertEqI(z, 0);
        }

        // kFarthestRows: farthest-first ordering vs brute force.
        void KFarthest()
        {
            int M = 5, N = 2;
            var A = GenerateOP.floatRandomMat(M, N, -2f, 2f, 99887, allocator: Allocator.Temp);
            var q = new floatN(N, Allocator.Temp);
            q[0] = (float)1; q[1] = (float)(-1);

            int k = 2;
            var idx = new Indices(k, Allocator.Temp);
            var scores = new floatN(k, Allocator.Temp);
            int cnt = Query.kFarthestRows(in A, in q, k, Metric.SqEuclidean, ref idx, ref scores);
            AssertEqI(cnt, k);

            var all = new floatN(M, Allocator.Temp);
            Query.distancesToRow(in A, in q, Metric.SqEuclidean, ref all);
            // farthest-first => descending distance
            for (int i = 0; i + 1 < cnt; i++)
                AssertTrue(scores[i] >= scores[i + 1] - sqrtEps());
            for (int i = 0; i < cnt; i++)
                AssertClose(scores[i], all[idx[i]], sqrtEps());
            // the k-th farthest returned is >= every non-selected row's distance
            float kth = scores[cnt - 1];
            for (int r = 0; r < M; r++)
            {
                bool selected = false;
                for (int i = 0; i < cnt; i++) if (idx[i] == r) selected = true;
                if (!selected) AssertTrue(all[r] <= kth + sqrtEps());
            }
        }

        // within-radius: inclusive boundary (<= r distance, >= r similarity); buffer fill matches count.
        void WithinRadiusBoundary()
        {
            //  r0=(0,0) r1=(3,4) r2=(1,1) ; q=(0,0).  Euclidean distances: 0, 5, sqrt2.
            var A = new floatMxN(3, 2, Allocator.Temp);
            A[0, 0] = (float)0; A[0, 1] = (float)0;
            A[1, 0] = (float)3; A[1, 1] = (float)4;
            A[2, 0] = (float)1; A[2, 1] = (float)1;
            var q = new floatN(2, Allocator.Temp);
            q[0] = (float)0; q[1] = (float)0;

            // radius exactly 5 (boundary): inclusive -> all three rows qualify.
            var idx = new Indices(3, Allocator.Temp);
            int cnt = Query.rowsWithinRadius(in A, in q, (float)5, Metric.Euclidean, ref idx);
            int ccnt = Query.countWithinRadius(in A, in q, (float)5, Metric.Euclidean);
            AssertEqI(cnt, 3); AssertEqI(ccnt, 3);
            // filled indices are 0,1,2 in scan order
            AssertEqI(idx[0], 0); AssertEqI(idx[1], 1); AssertEqI(idx[2], 2);

            // radius just under 5 -> r1 excluded (only the two close rows).
            int cnt2 = Query.rowsWithinRadius(in A, in q, (float)4.9, Metric.Euclidean, ref idx);
            AssertEqI(cnt2, 2);
            AssertEqI(idx[0], 0); AssertEqI(idx[1], 2);
            AssertEqI(Query.countWithinRadius(in A, in q, (float)4.9, Metric.Euclidean), 2);

            // similarity metric (Dot): inclusive >= r. q2=(1,0): dots 0, 3, 1.
            var q2 = new floatN(2, Allocator.Temp);
            q2[0] = (float)1; q2[1] = (float)0;
            // threshold exactly 1 -> rows with dot >= 1: r1(3) and r2(1). r0(0) excluded.
            int cnt3 = Query.rowsWithinRadius(in A, in q2, (float)1, Metric.Dot, ref idx);
            AssertEqI(cnt3, 2);
            AssertEqI(idx[0], 1); AssertEqI(idx[1], 2);
            AssertEqI(Query.countWithinRadius(in A, in q2, (float)1, Metric.Dot), 2);

            // Column twins. Columns of A length 3: c0=(0,3,1) c1=(0,4,1). qcol=(0,0,0).
            var qcol = new floatN(3, Allocator.Temp);
            qcol[0] = (float)0; qcol[1] = (float)0; qcol[2] = (float)0;
            // SqEuclidean: c0=0+9+1=10, c1=0+16+1=17. radius 10 inclusive -> only c0.
            var idxc = new Indices(2, Allocator.Temp);
            int ccol = Query.columnsWithinRadius(in A, in qcol, (float)10, Metric.SqEuclidean, ref idxc);
            AssertEqI(ccol, 1); AssertEqI(idxc[0], 0);
            AssertEqI(Query.countWithinColumnRadius(in A, in qcol, (float)10, Metric.SqEuclidean), 1);
        }

        // ---------------------------------------------------------------------
        // GROUP 4 — VALUE / MASK
        // ---------------------------------------------------------------------

        void FindValue()
        {
            var v = new floatN(5, Allocator.Temp);
            v[0] = (float)1; v[1] = (float)2; v[2] = (float)2; v[3] = (float)3; v[4] = (float)2;

            // first match (within tol 0) at index 1
            AssertEqI(Query.findValue(in v, (float)2, (float)0), 1);
            // absent -> -1
            AssertEqI(Query.findValue(in v, (float)9, (float)0), -1);
            // tol boundary, exactly representable in float+double: target 2.5, tol 0.5 matches the
            // 2's on the inclusive boundary (|2 - 2.5| = 0.5 <= 0.5) -> first 2 at index 1.
            AssertEqI(Query.findValue(in v, (float)2.5, (float)0.5), 1);
            // tol below the gap (|2 - 2.5| = 0.5 > 0.25, |3 - 2.5| = 0.5 > 0.25) -> no match.
            AssertEqI(Query.findValue(in v, (float)2.5, (float)0.25), -1);

            // matrix overload (flat index). 2x2 = [5, 6; 7, 6]; first 6 at flat 1.
            var A = new floatMxN(2, 2, Allocator.Temp);
            A[0, 0] = (float)5; A[0, 1] = (float)6;
            A[1, 0] = (float)7; A[1, 1] = (float)6;
            AssertEqI(Query.findValue(in A, (float)6, (float)0), 1);
        }

        void NonzeroCountNonzero()
        {
            var v = new floatN(6, Allocator.Temp);
            v[0] = (float)0;   v[1] = (float)0.5; v[2] = (float)0;
            v[3] = (float)(-3); v[4] = (float)0.05; v[5] = (float)0;

            // tol=0: nonzero are indices 1,3,4 -> count 3
            AssertEqI(Query.countNonzero(in v, (float)0), 3);
            var idx = new Indices(6, Allocator.Temp);
            int c = Query.nonzero(in v, (float)0, ref idx);
            AssertEqI(c, 3);
            AssertEqI(idx[0], 1); AssertEqI(idx[1], 3); AssertEqI(idx[2], 4);

            // tol=0.1: |0.05| filtered out -> indices 1,3 -> count 2
            AssertEqI(Query.countNonzero(in v, (float)0.1), 2);
            int c2 = Query.nonzero(in v, (float)0.1, ref idx);
            AssertEqI(c2, 2);
            AssertEqI(idx[0], 1); AssertEqI(idx[1], 3);

            // matrix overload, flat indices. 2x2 = [0,2;0,0] -> one nonzero at flat 1.
            var A = new floatMxN(2, 2, Allocator.Temp);
            A[0, 0] = (float)0; A[0, 1] = (float)2;
            A[1, 0] = (float)0; A[1, 1] = (float)0;
            AssertEqI(Query.countNonzero(in A, (float)0), 1);
            var idxA = new Indices(4, Allocator.Temp);
            int ca = Query.nonzero(in A, (float)0, ref idxA);
            AssertEqI(ca, 1); AssertEqI(idxA[0], 1);
        }

        // ---------------------------------------------------------------------
        // SYMMETRY: a column op on A == the row op on transpose(A).
        // ---------------------------------------------------------------------

        void Symmetry()
        {
            int M = 5, N = 4;
            var A = GenerateOP.floatRandomMat(M, N, -3f, 3f, 20240625, allocator: Allocator.Temp);
            var At = Blas.trans(A);   // N x M

            // For a column op on A, the query length is M_Rows = M; this same q is the row query
            // for At (whose N_Cols = M). So nearestColumn(A,q) == nearestRow(At,q).
            var q = new floatN(M, Allocator.Temp);
            for (int i = 0; i < M; i++) q[i] = (float)(i - 2) * (float)0.7;

            Query.nearestColumn(in A, in q, Metric.SqEuclidean, out int ci, out float cs);
            Query.nearestRow(in At, in q, Metric.SqEuclidean, out int ri, out float rs);
            AssertEqI(ci, ri); AssertClose(cs, rs, sqrtEps());

            // distancesToColumn(A) == distancesToRow(transpose(A)).
            var dc = new floatN(N, Allocator.Temp);
            var dr = new floatN(N, Allocator.Temp);
            Query.distancesToColumn(in A, in q, Metric.Euclidean, ref dc);
            Query.distancesToRow(in At, in q, Metric.Euclidean, ref dr);
            for (int j = 0; j < N; j++)
                AssertClose(dc[j], dr[j], sqrtEps());

            // colArgMin(A) == rowArgMin(transpose(A)): same per-column extreme indices.
            var colIdx = new Indices(N, Allocator.Temp);
            var colVal = new floatN(N, Allocator.Temp);
            Query.colArgMin(in A, ref colIdx, ref colVal);
            var rowIdx = new Indices(N, Allocator.Temp);
            var rowVal = new floatN(N, Allocator.Temp);
            Query.rowArgMin(in At, ref rowIdx, ref rowVal);
            for (int j = 0; j < N; j++)
            {
                AssertEqI(colIdx[j], rowIdx[j]);
                AssertClose(colVal[j], rowVal[j], sqrtEps());
            }

            // argMaxColNorm(A) == argMaxRowNorm(transpose(A)).
            AssertEqI(Query.argMaxColNorm(in A, Norm.L2),
                      Query.argMaxRowNorm(in At, Norm.L2));

            // farthestColumn(A) == farthestRow(transpose(A)).
            Query.farthestColumn(in A, in q, Metric.SqEuclidean, out int fci, out float fcs);
            Query.farthestRow(in At, in q, Metric.SqEuclidean, out int fri, out float frs);
            AssertEqI(fci, fri); AssertClose(fcs, frs, sqrtEps());

            // kNearestColumns(A) == kNearestRows(transpose(A)): same indices + scores.
            int kk = 3;
            var ncIdx = new Indices(kk, Allocator.Temp); var ncVal = new floatN(kk, Allocator.Temp);
            var nrIdx = new Indices(kk, Allocator.Temp); var nrVal = new floatN(kk, Allocator.Temp);
            int ncCnt = Query.kNearestColumns(in A, in q, kk, Metric.SqEuclidean, ref ncIdx, ref ncVal);
            int nrCnt = Query.kNearestRows(in At, in q, kk, Metric.SqEuclidean, ref nrIdx, ref nrVal);
            AssertEqI(ncCnt, nrCnt);
            for (int i = 0; i < ncCnt; i++)
            {
                AssertEqI(ncIdx[i], nrIdx[i]);
                AssertClose(ncVal[i], nrVal[i], sqrtEps());
            }

            // kFarthestColumns(A) == kFarthestRows(transpose(A)).
            var fcIdx = new Indices(kk, Allocator.Temp); var fcVal = new floatN(kk, Allocator.Temp);
            var frIdx = new Indices(kk, Allocator.Temp); var frVal = new floatN(kk, Allocator.Temp);
            int fcCnt = Query.kFarthestColumns(in A, in q, kk, Metric.SqEuclidean, ref fcIdx, ref fcVal);
            int frCnt = Query.kFarthestRows(in At, in q, kk, Metric.SqEuclidean, ref frIdx, ref frVal);
            AssertEqI(fcCnt, frCnt);
            for (int i = 0; i < fcCnt; i++)
            {
                AssertEqI(fcIdx[i], frIdx[i]);
                AssertClose(fcVal[i], frVal[i], sqrtEps());
            }

            // columnsWithinRadius(A) == rowsWithinRadius(transpose(A)); same for the count twin.
            float rad = (float)6;
            var cwrIdx = new Indices(N, Allocator.Temp);
            var rwrIdx = new Indices(N, Allocator.Temp);
            int cwrCnt = Query.columnsWithinRadius(in A, in q, rad, Metric.SqEuclidean, ref cwrIdx);
            int rwrCnt = Query.rowsWithinRadius(in At, in q, rad, Metric.SqEuclidean, ref rwrIdx);
            AssertEqI(cwrCnt, rwrCnt);
            for (int i = 0; i < cwrCnt; i++) AssertEqI(cwrIdx[i], rwrIdx[i]);
            AssertEqI(Query.countWithinColumnRadius(in A, in q, rad, Metric.SqEuclidean),
                      Query.countWithinRadius(in At, in q, rad, Metric.SqEuclidean));
        }

        // Standalone k-wrappers must CLAMP k to the matrix dimension:
        // calling with k > M_Rows / N_Cols returns count == min(k, dim) with NO exception, and
        // the result matches a brute-force top-/bottom-k.
        void ArenaKWrapperClamp()
        {
            int M = 4, N = 3;
            var A = GenerateOP.floatRandomMat(M, N, -3f, 3f, 13572468, allocator: Allocator.Temp);
            var q = new floatN(N, Allocator.Temp);
            q[0] = (float)0.5; q[1] = (float)(-1.5); q[2] = (float)1;
            var qc = new floatN(M, Allocator.Temp);
            for (int i = 0; i < M; i++) qc[i] = (float)(i - 1) * (float)0.5;

            int kRows = M + 5;   // k > M_Rows
            int kCols = N + 5;   // k > N_Cols

            // --- floatKNearestRows: clamp to M, ascending, matches brute force ---
            var nrIdx = Query.floatKNearestRows(in A, in q, kRows, Metric.SqEuclidean, out floatN nrScore, out int nrCnt, Allocator.Temp);
            AssertEqI(nrCnt, M);
            AssertEqI(nrIdx.N, M);
            var allR = new floatN(M, Allocator.Temp);
            Query.distancesToRow(in A, in q, Metric.SqEuclidean, ref allR);
            for (int i = 0; i + 1 < nrCnt; i++) AssertTrue(nrScore[i] <= nrScore[i + 1] + sqrtEps());
            for (int i = 0; i < nrCnt; i++) AssertClose(nrScore[i], allR[nrIdx[i]], sqrtEps());

            // --- floatKFarthestRows: clamp to M, descending ---
            var frIdx = Query.floatKFarthestRows(in A, in q, kRows, Metric.SqEuclidean, out floatN frScore, out int frCnt, Allocator.Temp);
            AssertEqI(frCnt, M);
            for (int i = 0; i + 1 < frCnt; i++) AssertTrue(frScore[i] >= frScore[i + 1] - sqrtEps());
            for (int i = 0; i < frCnt; i++) AssertClose(frScore[i], allR[frIdx[i]], sqrtEps());

            // --- floatKNearestColumns: clamp to N ---
            var ncIdx = Query.floatKNearestColumns(in A, in qc, kCols, Metric.SqEuclidean, out floatN ncScore, out int ncCnt, Allocator.Temp);
            AssertEqI(ncCnt, N);
            var allC = new floatN(N, Allocator.Temp);
            Query.distancesToColumn(in A, in qc, Metric.SqEuclidean, ref allC);
            for (int i = 0; i + 1 < ncCnt; i++) AssertTrue(ncScore[i] <= ncScore[i + 1] + sqrtEps());
            for (int i = 0; i < ncCnt; i++) AssertClose(ncScore[i], allC[ncIdx[i]], sqrtEps());

            // --- floatKFarthestColumns: clamp to N ---
            var fcIdx = Query.floatKFarthestColumns(in A, in qc, kCols, Metric.SqEuclidean, out floatN fcScore, out int fcCnt, Allocator.Temp);
            AssertEqI(fcCnt, N);
            for (int i = 0; i + 1 < fcCnt; i++) AssertTrue(fcScore[i] >= fcScore[i + 1] - sqrtEps());
            for (int i = 0; i < fcCnt; i++) AssertClose(fcScore[i], allC[fcIdx[i]], sqrtEps());
        }

        // ---------------------------------------------------------------------
        // ALLOCATING WRAPPERS — each allocating wrapper matches the zero-alloc primitive.
        // ---------------------------------------------------------------------

        void ArenaWrappers()
        {
            int M = 6, N = 4;
            var A = GenerateOP.floatRandomMat(M, N, -2f, 2f, 7777, allocator: Allocator.Temp);
            var q = new floatN(N, Allocator.Temp);
            for (int i = 0; i < N; i++) q[i] = (float)(i) * (float)0.3 - (float)0.5;

            // --- floatDistancesToRow / Column wrappers vs primitive ---
            var dr = Query.floatDistancesToRow(in A, in q, Metric.SqEuclidean);
            var drRef = new floatN(M, Allocator.Temp);
            Query.distancesToRow(in A, in q, Metric.SqEuclidean, ref drRef);
            AssertEqI(dr.N, M);
            for (int i = 0; i < M; i++) AssertClose(dr[i], drRef[i], sqrtEps());

            var qc = new floatN(M, Allocator.Temp);
            for (int i = 0; i < M; i++) qc[i] = (float)(i) * (float)0.2;
            var dcol = Query.floatDistancesToColumn(in A, in qc, Metric.SqEuclidean);
            var dcolRef = new floatN(N, Allocator.Temp);
            Query.distancesToColumn(in A, in qc, Metric.SqEuclidean, ref dcolRef);
            AssertEqI(dcol.N, N);
            for (int j = 0; j < N; j++) AssertClose(dcol[j], dcolRef[j], sqrtEps());

            // --- floatNonzeroIndices: exact-sized, contents match the primitive ---
            var idxNz = Query.floatNonzeroIndices(in A, (float)0.5, allocator: Allocator.Temp);
            var refNz = new Indices(M * N, Allocator.Temp);
            int refCnt = Query.nonzero(in A, (float)0.5, ref refNz);
            AssertEqI(idxNz.N, refCnt);
            for (int i = 0; i < refCnt; i++) AssertEqI(idxNz[i], refNz[i]);

            // --- floatRowsWithinRadius: exact-sized, contents match the primitive ---
            float radius = (float)5;
            var idxRR = Query.floatRowsWithinRadius(in A, in q, radius, Metric.SqEuclidean, allocator: Allocator.Temp);
            var refRR = new Indices(M, Allocator.Temp);
            int refRRcnt = Query.rowsWithinRadius(in A, in q, radius, Metric.SqEuclidean, ref refRR);
            AssertEqI(idxRR.N, refRRcnt);
            for (int i = 0; i < refRRcnt; i++) AssertEqI(idxRR[i], refRR[i]);

            // --- floatColumnsWithinRadius ---
            var idxCR = Query.floatColumnsWithinRadius(in A, in qc, (float)8, Metric.SqEuclidean, allocator: Allocator.Temp);
            var refCR = new Indices(N, Allocator.Temp);
            int refCRcnt = Query.columnsWithinRadius(in A, in qc, (float)8, Metric.SqEuclidean, ref refCR);
            AssertEqI(idxCR.N, refCRcnt);
            for (int i = 0; i < refCRcnt; i++) AssertEqI(idxCR[i], refCR[i]);

            // --- floatKNearestRows: idx + scores match the primitive ---
            int k = 3;
            var idxK = Query.floatKNearestRows(in A, in q, k, Metric.SqEuclidean, out floatN scoresK, out int cntK, Allocator.Temp);
            var refIdxK = new Indices(k, Allocator.Temp);
            var refScoresK = new floatN(k, Allocator.Temp);
            int refCntK = Query.kNearestRows(in A, in q, k, Metric.SqEuclidean, ref refIdxK, ref refScoresK);
            AssertEqI(cntK, refCntK);
            AssertEqI(idxK.N, refCntK);
            for (int i = 0; i < refCntK; i++)
            {
                AssertEqI(idxK[i], refIdxK[i]);
                AssertClose(scoresK[i], refScoresK[i], sqrtEps());
            }

            // --- floatKNearestColumns ---
            var idxKC = Query.floatKNearestColumns(in A, in qc, k, Metric.SqEuclidean, out floatN scoresKC, out int cntKC, Allocator.Temp);
            var refIdxKC = new Indices(k, Allocator.Temp);
            var refScoresKC = new floatN(k, Allocator.Temp);
            int refCntKC = Query.kNearestColumns(in A, in qc, k, Metric.SqEuclidean, ref refIdxKC, ref refScoresKC);
            AssertEqI(cntKC, refCntKC);
            for (int i = 0; i < refCntKC; i++)
            {
                AssertEqI(idxKC[i], refIdxKC[i]);
                AssertClose(scoresKC[i], refScoresKC[i], sqrtEps());
            }
        }

        // ---------------------------------------------------------------------
        // helpers
        // ---------------------------------------------------------------------

        // Per-precision tolerances: float needs looser epsilons than double.
        // floatSqrtEps expands to float (3.45e-4) / double (1.49e-8).
        static float sqrtEps() => (float)Consts.floatSqrtEps;
        static float fEps() => (float)(100 * Consts.floatEpsilon);

        // Fail layout: [0]=flag, [1]=got, [2]=expected, [3]=diff
        void AssertClose(float a, float b, float precision)
        {
            float diff = math.abs(a - b);
            if (!(diff <= precision) && Fail[0] == (float)0)
            {
                Fail[0] = (float)1;
                Fail[1] = a;
                Fail[2] = b;
                Fail[3] = diff;
            }
            Assert.IsTrue(diff <= precision);
        }

        void AssertEqI(int got, int expected)
        {
            if (got != expected && Fail[0] == (float)0)
            {
                Fail[0] = (float)1;
                Fail[1] = got;
                Fail[2] = expected;
                Fail[3] = got - expected;
            }
            Assert.AreEqual(expected, got);
        }

        void AssertTrue(bool ok)
        {
            if (!ok && Fail[0] == (float)0)
            {
                Fail[0] = (float)1;
                Fail[1] = (float)(-1);
                Fail[2] = (float)(-1);
                Fail[3] = (float)(-1);
            }
            Assert.IsTrue(ok);
        }
    }

    void RunJob(TestJob.TestType type)
    {
        var fail = new NativeArray<float>(4, Allocator.TempJob);
        try
        {
            new TestJob() { Type = type, Fail = fail }.Run();
            if (fail[0] != (float)0)
                Assert.Fail($"got {fail[1]}, expected {fail[2]}, diff {fail[3]}");
        }
        catch (Exception e)
        {
            if (fail[0] != (float)0)
                Assert.Fail($"{type}: got {fail[1]}, expected {fail[2]}, diff {fail[3]} ({e.Message})");
            throw;
        }
        finally
        {
            fail.Dispose();
        }
    }

